glsl3.vert:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
in vec3 a_position;
in vec2 a_texCoord;
in vec4 a_color;
out vec4 color;
out vec2 mapUv;
vec4 vert () {
  mapUv = vec2(a_texCoord.x, 1.0 - a_texCoord.y);
  color = a_color;
  return cc_matViewProj * vec4(a_position, 1.0);
}
void main() { gl_Position = vert(); }

glsl3.frag:
precision highp float;
in vec4 color;
in vec2 mapUv;
layout(std140) uniform TerrainBlend {
  vec4 tileParams;
  vec4 mapParams;
};
uniform sampler2D turfGrass;
uniform sampler2D turfSavanna;
uniform sampler2D turfForest;
uniform sampler2D turfRocky;
uniform sampler2D turfRuins;
uniform sampler2D turfAsh;
uniform sampler2D maskW0123;
uniform sampler2D maskW45;
vec4 frag () {
  vec2 mapSize = max(mapParams.xy, vec2(1.0));
  vec2 p = mapUv * mapSize;
  vec2 maskUv = vec2(mapUv.x, 1.0 - mapUv.y);
  vec4 w0123 = texture(maskW0123, maskUv);
  vec2 w45 = texture(maskW45, maskUv).rg;
  float sharp = max(tileParams.y, 0.01);
  w0123 = pow(w0123, vec4(sharp));
  w45 = pow(w45, vec2(sharp));
  float total = dot(w0123, vec4(1.0)) + w45.x + w45.y;
  vec2 tileUv = vec2(p.x, -p.y) / max(tileParams.x, 0.01);
  vec3 c = texture(turfGrass, tileUv).rgb * w0123.r
         + texture(turfSavanna, tileUv).rgb * w0123.g
         + texture(turfForest, tileUv).rgb * w0123.b
         + texture(turfRocky, tileUv).rgb * w0123.a
         + texture(turfRuins, tileUv).rgb * w45.x
         + texture(turfAsh, tileUv).rgb * w45.y;
  c /= max(total, 1e-6);
  if (tileParams.w > 0.0) {
    float d = min(min(p.x, mapSize.x - p.x), min(p.y, mapSize.y - p.y));
    float band = pow(clamp(1.0 - d / tileParams.w, 0.0, 1.0), 1.3);
    c *= 1.0 - tileParams.z * band;
  }
  c *= mapParams.z;
  return vec4(c, 1.0) * color;
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

glsl1.vert:
precision highp float;
uniform highp mat4 cc_matViewProj;
attribute vec3 a_position;
attribute vec2 a_texCoord;
attribute vec4 a_color;
varying vec4 color;
varying vec2 mapUv;
vec4 vert () {
  mapUv = vec2(a_texCoord.x, 1.0 - a_texCoord.y);
  color = a_color;
  return cc_matViewProj * vec4(a_position, 1.0);
}
void main() { gl_Position = vert(); }

