         + texture2D(turfSavanna, tileUv).rgb * w0123.g
         + texture2D(turfForest, tileUv).rgb * w0123.b
         + texture2D(turfRocky, tileUv).rgb * w0123.a
         + texture2D(turfRuins, tileUv).rgb * w45.x
